// - This file was wholly generated by an assortment of LLM models with some supervision near 2026-08-11.

import { useRef, useState } from "react";
import type { BrowseItem, MangoError, MangoSettings, MangoSource, UmlState, ImportToMangoHandle } from "./types";

// ═══════════════════════════════════════════════════════════════════════
// AUTOMATED LOGIC — the sequencer.
//
// The automatic-transition engine behind the numbered API further down:
// timing gates, caption scheduling, and the progress-ring snap-reset.
// Nothing in this half of the file is called directly by a host importer,
// and none of it is numbered — it's the unordered machinery the numbered
// calls drive. If you're looking for what a host is meant to call, and in
// what order, skip to THE NUMBERED API below.
//
// THE GATE, in one paragraph: the carton's pack → travel → scan animation
// takes a fixed, CSS-authored amount of time to play out visually, but the
// host's real work (parsing a file, calling an API) can finish faster or
// slower than that. `gate.current.at` is the timestamp the animation is
// expected to finish; scanned()/reject() below both wait until then before
// revealing the outcome (via afterGate()), so a scan that resolves in
// 50ms still gets its full, watchable trip through the scanner instead of
// jump-cutting straight to the result.
// ═══════════════════════════════════════════════════════════════════════

function reducedMotion() {
  return typeof matchMedia === "function" && matchMedia("(prefers-reduced-motion: reduce)").matches;
}

const MAX_ROWS = 14;

/**
 * Owns every piece of state and timing machinery the import sequence
 * needs, plus the primitives (dropGate, openGate, afterGate, setProgress,
 * ...) that createImportCommands() below composes into the public API.
 * Not exported for use outside this file's two halves.
 *
 * @param initialSource the sources key selected before any import begins
 */
export function useImportSequencer(initialSource: string) {
  const rootRef = useRef<HTMLElement>(null);

  const [state, setState] = useState<UmlState>("closed");
  const [source, setSource] = useState(initialSource);
  const [doomed, setDoomed] = useState(false);
  const [failing, setFailing] = useState(false);
  const [errored, setErrored] = useState(false);
  const [errorInfo, setErrorInfo] = useState<MangoError>({ title: "" });
  const [stageCaption, setStageCaption] = useState("Packing Your Data");
  const [foundCount, setFoundCount] = useState(0);
  const [tally, setTally] = useState({ nodes: 0, projects: 0, skipped: 0 });
  const [rows, setRows] = useState<string[]>([]);
  const [browseItems, setBrowseItems] = useState<BrowseItem[]>([]);

  // Imperative bookkeeping for the scan gate and progress ring — timers and a
  // CSS transition to interrupt, so refs rather than state. See
  // importToMango.css / --flap-a for the rule this component follows:
  // things a browser already animates don't need React re-renders riding along.
  const count = useRef({ processed: 0, total: 0 });
  const gate = useRef({ at: 0, timer: undefined as ReturnType<typeof setTimeout> | undefined });
  const failTimer = useRef<ReturnType<typeof setTimeout>>();
  const captionTimers = useRef<ReturnType<typeof setTimeout>[]>([]);
  const lastProgress = useRef(0);

  /** Reads the handful of CSS-authored stage durations createImportCommands() needs to schedule timeouts against, in seconds, with sane fallbacks if a custom property is missing or malformed. */
  function stageSeconds() {
    const root = rootRef.current;
    const cs = root ? getComputedStyle(root) : null;
    const seconds = (prop: string, fallback: number) => {
      const raw = cs?.getPropertyValue(prop).trim();
      if (!raw) return fallback;
      const n = parseFloat(raw);
      if (!isFinite(n) || n < 0) return fallback;
      return /ms$/i.test(raw) ? n / 1000 : n;
    };
    return {
      pack: seconds("--uml-t-pack", 3.4),
      travel: seconds("--uml-t-travel", 3.4),
      scan: seconds("--uml-t-scan", 3.6),
      failHold: seconds("--uml-t-fail-hold", 1.15),
      rewind: seconds("--uml-t-rewind", 2.2),
    };
  }

  /** Cancels any pending gate timer and clears the failure flags — the shared reset used at the start of a new run and by reset()/finish(). */
  function dropGate() {
    clearTimeout(gate.current.timer);
    gate.current.timer = undefined;
    gate.current.at = 0;
    clearTimeout(failTimer.current);
    failTimer.current = undefined;
    setFailing(false);
    setDoomed(false);
    setErrored(false);
  }

  function clearCaptionTimers() {
    captionTimers.current.forEach(clearTimeout);
    captionTimers.current = [];
  }

  /** Runs fn() now if the gate has already elapsed, or schedules it for the moment it does — see THE GATE, above. Shared by scanned() and reject(), the two calls that can arrive before the carton has finished its visible trip. */
  function afterGate(fn: () => void) {
    const wait = gate.current.at - Date.now();
    if (wait > 0) {
      clearTimeout(gate.current.timer);
      gate.current.timer = setTimeout(fn, wait);
      return;
    }
    fn();
  }

  /** The gate has been satisfied and the scan succeeded: show the settings review. */
  function openGate() {
    clearCaptionTimers();
    setStageCaption("Check Your Settings");
    setState("review");
  }

  // --uml-progress is CSS-transitioned so ordinary forward progress glides.
  // Starting a new import at 0 after a finished one at 100 has to skip that
  // transition, or the ring visibly counts backwards first — same
  // suppress/reflow/restore trick the original used.
  function setProgress(next: number) {
    const root = rootRef.current;
    lastProgress.current = next;
    if (!root) return;
    if (next < parseFloat(root.dataset.umlProgress ?? "0")) {
      const prev = root.style.transition;
      root.style.transition = "none";
      void root.offsetWidth;
      root.style.setProperty("--uml-progress", String(next));
      void root.offsetWidth;
      root.style.transition = prev;
    } else {
      root.style.setProperty("--uml-progress", String(next));
    }
    root.dataset.umlProgress = String(next);
  }

  return {
    rootRef,
    state, setState,
    source, setSource,
    doomed, setDoomed,
    failing, setFailing,
    errored, setErrored,
    errorInfo, setErrorInfo,
    stageCaption, setStageCaption,
    foundCount, setFoundCount,
    tally, setTally,
    rows, setRows,
    browseItems, setBrowseItems,
    count, gate, failTimer, captionTimers, lastProgress,
    stageSeconds, dropGate, clearCaptionTimers, afterGate, openGate, setProgress,
  };
}

export type ImportSequencer = ReturnType<typeof useImportSequencer>;

// ═══════════════════════════════════════════════════════════════════════
// THE NUMBERED API — what a host importer calls, and in what order.
//
// This is the whole public contract: every method a real import loop calls,
// numbered by where it falls in a normal run (1 → 6). Steps sharing a
// number are either alternatives — only one of them happens (3a vs. 3b) —
// or repeat in a loop while an import runs (4, 4a-4c); noted on each one.
// setBrowseItems isn't part of the sequence at all and is callable any time.
//
// Nothing in here is automated — every line only runs because a host
// called it. importToMango.tsx just wires this up to a ref; it has no
// opinion on when any of these fire.
// ═══════════════════════════════════════════════════════════════════════

/**
 * Builds the ImportToMangoHandle a host drives an import through. A
 * factory, not a class, so it can close over the sequencer's setters and
 * the live sources/settings without an extra layer of indirection.
 *
 * @param seq the sequencer instance from useImportSequencer()
 * @param sources the component's `sources` prop, for resolving begin()'s source key
 * @param settings the live settings-form values, returned by the `settings` getter
 * @param closeDesk closes the settings sheet — called at the start of a run and after a rejection
 */
export function createImportCommands(
  seq: ImportSequencer,
  sources: Record<string, MangoSource>,
  settings: MangoSettings,
  closeDesk: () => void,
): ImportToMangoHandle {
  const handle: ImportToMangoHandle = {
    // 1. Start a run: pack the carton, hold under the scanner.
    begin({ source: src, fileName }) {
      const key = src && sources[src] ? src : Object.keys(sources)[0];
      seq.setSource(key ?? "");
      closeDesk();
      seq.setRows([]);
      seq.count.current = { processed: 0, total: 0 };
      seq.setProgress(0);
      seq.setStageCaption(fileName ? `Packing ${fileName}` : "Packing your data");
      seq.setState("scanning");

      const t = seq.stageSeconds();
      seq.dropGate();
      seq.gate.current.at = reducedMotion() ? 0 : Date.now() + (t.pack + t.travel + t.scan) * 1000;

      seq.clearCaptionTimers();
      seq.captionTimers.current = [
        setTimeout(() => seq.setStageCaption("Scanning and Mapping"), (t.pack + t.travel) * 1000),
      ];
    },

    // 2. How many records the file/API actually contains.
    found(n) {
      seq.count.current.total = Math.max(0, Math.round(Number(n) || 0));
      seq.setFoundCount(seq.count.current.total);
    },

    // 3a. Scan succeeded — advance to the settings review. Alternative to reject() (3b).
    scanned(n) {
      if (n != null) handle.found(n);
      seq.afterGate(seq.openGate);
    },

    // 3b. Scan failed — plays the whole sequence in reverse. Alternative to scanned() (3a).
    reject(err) {
      const e: MangoError = typeof err === "string" ? { title: err } : err;
      const title = e.title || "Import failed";
      const detail = e.detail || "";

      seq.setDoomed(true); // immediately — the x-ray contents must never light up

      seq.afterGate(() => {
        seq.setFailing(true);
        seq.setStageCaption(title);
        clearTimeout(seq.failTimer.current);
        const t = seq.stageSeconds();
        seq.failTimer.current = setTimeout(() => {
          seq.setFailing(false);
          seq.setDoomed(false);
          seq.clearCaptionTimers();
          seq.setStageCaption("Packing Your Data");
          seq.setProgress(0);
          seq.setState("open");
          seq.setErrorInfo({ title, detail });
          closeDesk();
          seq.setErrored(true);
        }, (t.failHold + t.rewind) * 1000);
      });
    },

    // 4. One record done — call once per item while importing, in a loop.
    item(name) {
      seq.count.current.processed++;
      if (name != null) handle.parsing(name);
      if (seq.count.current.total > 0) {
        handle.progress((seq.count.current.processed / seq.count.current.total) * 100);
      }
    },

    // 4a. Queue names without counting them yet (seen, not written). Loops alongside item().
    parsing(text) {
      const incoming = Array.isArray(text) ? text : [text];
      seq.setRows((prev) => {
        const next = [...prev, ...incoming.filter((t) => t != null && t !== "")];
        return next.slice(-MAX_ROWS);
      });
    },

    // 4a. Replace the queued names outright.
    items(list) {
      seq.setRows(list.filter((x) => x != null && x !== "").slice(-MAX_ROWS));
    },

    // 4b. Update the three completion-screen tallies. Loops alongside item().
    counts({ nodes, projects, skipped }) {
      seq.setTally((prev) => ({
        nodes: nodes ?? prev.nodes,
        projects: projects ?? prev.projects,
        skipped: skipped ?? prev.skipped,
      }));
    },

    // 4c. Set the ring directly, if you're not using item() to derive it.
    progress(n) {
      seq.setProgress(Math.max(0, Math.min(100, Math.round(Number(n) || 0))));
    },

    // 5. Import complete — ring to 100, completion screen.
    finish() {
      seq.dropGate();
      seq.clearCaptionTimers();
      handle.progress(100);
      seq.setStageCaption("Import Complete");
      seq.setState("done");
    },

    // 6. Back to closed — call to let the user start over.
    reset() {
      seq.dropGate();
      seq.clearCaptionTimers();
      seq.setRows([]);
      seq.count.current = { processed: 0, total: 0 };
      seq.setProgress(0);
      seq.setStageCaption("Packing Your Data");
      seq.setState("closed");
    },

    // Not part of the sequence — callable any time after found() (2).
    setBrowseItems(items) {
      seq.setBrowseItems(items);
    },

    get settings() {
      return settings;
    },
    get value() {
      return seq.lastProgress.current;
    },
    get processed() {
      return seq.count.current.processed;
    },
    get total() {
      return seq.count.current.total;
    },
  };
  return handle;
}
